def total(a): return 1.5*a[8]+a[9]+a[10]+a[11]+a[12]

out=[]
out.append("# 02 — Avenues catalog (50 ideas, scored)\n\n[← back to README](README.md)\n")
out.append("Each avenue is tied to one categorical concept (see [05_category_theory_primer.md](05_category_theory_primer.md)). Citation keys refer to [01_literature_map.md](01_literature_map.md).\n")
out.append("**Scoring (1–5, 5 = best; judgement calls, not measurements).** **F** feasibility for an undergrad with modest compute and no big API budget · **N** novelty (5 = no one seems to have done it, given the search limits in the [notes](CHANGELOG_or_NOTES.md)) · **S** safety relevance · **C** connection to Will's existing pipeline (`will/project1`, `dag_codes`) · **T** time to first result (5 = days, 1 = months). **Total = 1.5·F + N + S + C + T** (max 27.5).\n")
out.append("> **Novelty caveat.** Novelty scores reflect only what the literature agents could find through web search (arXiv itself was not reachable). Re-search arXiv for 2026 preprints before claiming novelty for any avenue. The field is moving fast: two 2026 papers ([`bottman2026operadic`](01_literature_map.md), [`liu2026intent`](01_literature_map.md)) already cover the core of Will's current test.\n")
out.append("## Ranked table\n")
out.append("| Rank | ID | Avenue | Concept | F | N | S | C | T | Total | Pilot |")
out.append("|---:|---|---|---|---:|---:|---:|---:|---:|---:|---|")
for i,a in enumerate(sorted(A,key=lambda a:-total(a)),1):
    out.append(f"| {i} | [{a[0]}](#{a[0].lower()}) | {a[1]} | {a[2]} | {a[8]} | {a[9]} | {a[10]} | {a[11]} | {a[12]} | {total(a):.1f} | {'yes' if a[13] else ''} |")
fam={'A':'Functors & composition','P':'Markov categories & information','N':'Natural transformations','D':'Duals / dagger','S':'Sheaves & cohomology','G':'Galois connections & adjunctions','L':'Lenses, optics & open games','O':'Operads & monoidal structure','Y':'Yoneda','X':'Speculative (Kan extensions, magnitude, fibrations)'}
out.append("\n## Per-avenue entries\n")
cur=None
for a in A:
    if a[0][0]!=cur:
        cur=a[0][0]; out.append(f"\n### Family {cur}: {fam[cur]}\n")
    out.append(f'<a id="{a[0].lower()}"></a>\n#### {a[0]}. {a[1]}')
    out.append(f"- **Concept:** {a[2]}")
    out.append(f"- **Idea:** {a[3]}")
    out.append(f"- **Safety relevance:** {a[4]}")
    out.append(f"- **Measurable quantity:** {a[5]}")
    out.append(f"- **Closest prior work:** {a[6]}")
    out.append(f"- **Novelty risk:** {a[7]}")
    out.append(f"- **Scores:** F{a[8]} N{a[9]} S{a[10]} C{a[11]} T{a[12]} → **{total(a):.1f}**" + (f"  · **Pilot:** {a[13]}" if a[13] else ""))
    out.append("")
print("\n".join(out))
